  <section id="shop-products"><SectionTitle title="Compare & earn" side={`${visible.length} deals`}/>{visible.length?<div className="grid gap-3 md:grid-cols-2">{visible.map(p=><button key={p.name} onClick={()=>setSelected(p.name)} className="rounded-2xl border border-[#ece9f2] bg-white p-4 text-left transition hover:-translate-y-0.5 hover:border-violet-200 hover:shadow-md"><div className="flex gap-3"><span className="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-gradient-to-br from-violet-50 to-pink-50 text-3xl">{p.icon}</span><span className="min-w-0 flex-1"><span className="text-[10px] font-black uppercase tracking-wider text-violet-500">{p.category}</span><b className="mt-0.5 block truncate text-sm text-[#282133]">{p.name}</b><span className="text-xs text-slate-500">{p.subtitle}</span></span></div><div className="mt-4 flex items-end justify-between border-t border-[#f0edf5] pt-3"><span><span className="block text-[10px] text-slate-400">Best price</span><b className="text-base text-[#241d34]">{p.best}</b></span><span className="rounded-full bg-emerald-50 px-3 py-1.5 text-xs font-black text-emerald-700">Earn {p.earn}</span></div></button>)}</div>:<EmptyState icon={Search} title="No matching deals" body="Try another product name or category."/>}</section>
